type BaseQuestion = {
    name: string;
    message: string;
};
type TextQuestion = BaseQuestion & {
    type: 'text';
    validate?: (value: string) => boolean | Promise<boolean>;
};
type NumberQuestion = BaseQuestion & {
    type: 'number';
    validate?: (value: number) => boolean | Promise<boolean>;
};
type ConfirmQuestion = BaseQuestion & {
    type: 'confirm';
    initial?: boolean;
};
type Options = {
    onCancel?: () => void;
};
export default function prompts(question: ConfirmQuestion, options?: Options): Promise<Record<string, boolean>>;
export default function prompts(question: NumberQuestion, options?: Options): Promise<Record<string, number>>;
export default function prompts(question: TextQuestion, options?: Options): Promise<Record<string, string>>;
export {};
